package com.shivhub.backend.entity;
import java.time.LocalDateTime; import com.shivhub.backend.enums.MarketplaceReportStatus; import jakarta.persistence.*; import lombok.Data;
@Entity @Table(name="marketplace_reports") @Data public class MarketplaceReport { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="listing_id",nullable=false) private MarketplaceListing listing; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reporter_id",nullable=false) private User reporter; @Column(nullable=false,length=80) private String reason; @Column(columnDefinition="TEXT") private String details; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private MarketplaceReportStatus status=MarketplaceReportStatus.OPEN; @Column(name="admin_remarks",columnDefinition="TEXT") private String adminRemarks; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} }
